#include <stdio.h>
#include <string.h>
#define INF 1000000000
#define MAXN 50
#define MAXC 8
#define MAXD 300

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define INF_LL ((long long)4e18)

typedef struct {
    int to;
    int dist;
    int company;
    int next;
} Edge;

typedef struct {
    int n;
    int *head;
    Edge *edges;
    int ecnt;
    int ecap;
} Graph;

typedef struct {
    long long dist;
    int node;
} HeapNode;

typedef struct {
    HeapNode *a;
    int size;
    int cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 1));
    h->size = 0;
    h->cap = cap;
}

static void heap_push(MinHeap *h, long long dist, int node) {
    if (h->size + 1 > h->cap) {
        h->cap *= 2;
        h->a = (HeapNode *)realloc(h->a, sizeof(HeapNode) * (h->cap + 1));
    }
    int i = ++h->size;
    while (i > 1 && h->a[i / 2].dist > dist) {
        h->a[i] = h->a[i / 2];
        i /= 2;
    }
    h->a[i].dist = dist;
    h->a[i].node = node;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->size--];
    int i = 1, child;
    while ((child = i * 2) <= h->size) {
        if (child + 1 <= h->size && h->a[child + 1].dist < h->a[child].dist) child++;
        if (h->a[child].dist >= last.dist) break;
        h->a[i] = h->a[child];
        i = child;
    }
    h->a[i] = last;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->size == 0;
}

static void graph_init(Graph *g, int n, int m) {
    g->n = n;
    g->head = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) g->head[i] = -1;
    g->ecap = (m > 0 ? 2 * m : 2);
    g->edges = (Edge *)malloc(sizeof(Edge) * g->ecap);
    g->ecnt = 0;
}

static void graph_add_edge(Graph *g, int u, int v, int dist, int company) {
    if (g->ecnt >= g->ecap) {
        g->ecap *= 2;
        g->edges = (Edge *)realloc(g->edges, sizeof(Edge) * g->ecap);
    }
    g->edges[g->ecnt].to = v;
    g->edges[g->ecnt].dist = dist;
    g->edges[g->ecnt].company = company;
    g->edges[g->ecnt].next = g->head[u];
    g->head[u] = g->ecnt++;
}

static long long fare_cost(int company, int distance, int maxd, long long **fare) {
    if (distance > maxd) return INF_LL;
    return fare[company][distance];
}

int main(void) {
    int N, M, C, S, G;

    while (scanf("%d %d %d %d %d", &N, &M, &C, &S, &G) == 5) {
        if (N == 0 && M == 0 && C == 0 && S == 0 && G == 0) break;

        S--;
        G--;

        Graph g;
        graph_init(&g, N, M);

        int totalDist = 0;
        for (int i = 0; i < M; i++) {
            int a, b, d, c;
            scanf("%d %d %d %d", &a, &b, &d, &c);
            a--; b--; c--;
            graph_add_edge(&g, a, b, d, c);
            graph_add_edge(&g, b, a, d, c);
            totalDist += d;
        }

        int *K = (int *)malloc(sizeof(int) * C);
        int maxK = 0;
        for (int i = 0; i < C; i++) {
            scanf("%d", &K[i]);
            if (K[i] > maxK) maxK = K[i];
        }

        long long **fare = (long long **)malloc(sizeof(long long *) * C);
        for (int i = 0; i < C; i++) {
            fare[i] = (long long *)malloc(sizeof(long long) * (K[i] + 1));
            fare[i][0] = 0;
            for (int j = 1; j <= K[i]; j++) {
                scanf("%lld", &fare[i][j]);
            }
        }

        /*
         * State:
         *   (station, company, accumulated_distance_on_that_company_segment)
         * plus a special "free" state meaning currently not riding any company.
         *
         * We may continue on same company accumulating distance.
         * We may stop a ride at any station, paying fare table for that accumulated distance.
         * Then start another company's ride from that station.
         *
         * Build Dijkstra over expanded states.
         */

        int freeStateBase = 0;
        int *offset = (int *)malloc(sizeof(int) * C);
        int stateCount = N; /* free states: one per station */

        for (int c = 0; c < C; c++) {
            offset[c] = stateCount;
            stateCount += N * K[c];
        }

        long long *dist = (long long *)malloc(sizeof(long long) * stateCount);
        for (int i = 0; i < stateCount; i++) dist[i] = INF_LL;

        MinHeap pq;
        heap_init(&pq, stateCount + 5);

        dist[S] = 0;
        heap_push(&pq, 0, S);

        while (!heap_empty(&pq)) {
            HeapNode cur = heap_pop(&pq);
            long long cd = cur.dist;
            int id = cur.node;
            if (cd != dist[id]) continue;

            if (id < N) {
                int u = id;

                for (int ei = g.head[u]; ei != -1; ei = g.edges[ei].next) {
                    Edge *e = &g.edges[ei];
                    int c = e->company;
                    int d = e->dist;
                    if (d <= K[c]) {
                        int nid = offset[c] + u * K[c] + (d - 1);
                        if (dist[nid] > cd) {
                            dist[nid] = cd;
                            heap_push(&pq, cd, nid);
                        }
                    }
                }
            } else {
                int company = -1, base = -1;
                for (int c = 0; c < C; c++) {
                    int begin = offset[c];
                    int end = begin + N * K[c];
                    if (id >= begin && id < end) {
                        company = c;
                        base = begin;
                        break;
                    }
                }

                int rem = id - base;
                int u = rem / K[company];
                int acc = rem % K[company] + 1;

                long long paid = cd + fare_cost(company, acc, K[company], fare);
                if (paid < dist[u]) {
                    dist[u] = paid;
                    heap_push(&pq, paid, u);
                }

                for (int ei = g.head[u]; ei != -1; ei = g.edges[ei].next) {
                    Edge *e = &g.edges[ei];
                    if (e->company != company) continue;
                    int nd = acc + e->dist;
                    if (nd <= K[company]) {
                        int nid = offset[company] + e->to * K[company] + (nd - 1);
                        if (dist[nid] > cd) {
                            dist[nid] = cd;
                            heap_push(&pq, cd, nid);
                        }
                    }
                }
            }
        }

        long long ans = dist[G];
        if (ans >= INF_LL / 2) printf("-1\n");
        else printf("%lld\n", ans);

        free(g.head);
        free(g.edges);
        for (int i = 0; i < C; i++) free(fare[i]);
        free(fare);
        free(K);
        free(offset);
        free(dist);
        free(pq.a);
    }

    return 0;
}

