    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            if (n == 0 && m == 0) break;

            int start = sc.nextInt();
            int goal = sc.nextInt();

            int[] companies = new int[m];
            int[] distances = new int[m];
            int[] from = new int[m];
            int[] to = new int[m];

            int maxCompany = 0;
            for (int i = 0; i < m; i++) {
                from[i] = sc.nextInt();
                to[i] = sc.nextInt();
                distances[i] = sc.nextInt();
                companies[i] = sc.nextInt();
                maxCompany = Math.max(maxCompany, companies[i]);
            }

            // Fare tables for each company
            int[][] fareTables = new int[maxCompany + 1][];
            for (int i = 1; i <= maxCompany; i++) {
                int c = sc.nextInt();
                fareTables[i] = new int[c + 1];
                fareTables[i][0] = 0;
                for (int j = 1; j <= c; j++) {
                    fareTables[i][j] = sc.nextInt();
                }
            }

            // Build graph
            List<Edge>[] graph = new ArrayList[n];
            for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
            for (int i = 0; i < m; i++) {
                graph[from[i]].add(new Edge(to[i], distances[i], companies[i]));
                graph[to[i]].add(new Edge(from[i], distances[i], companies[i]));
            }

            // Dijkstra: (station, totalCost)
            int[] dist = new int[n];
            Arrays.fill(dist, Integer.MAX_VALUE);
            dist[start] = 0;
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
            pq.offer(new int[]{start, 0});

            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int u = cur[0];
                int cost = cur[1];
                if (cost > dist[u]) continue;
                if (u == goal) break;

                for (Edge e : graph[u]) {
                    int newCost = cost + getFare(fareTables[e.company], e.dist);
                    if (newCost < dist[e.to]) {
                        dist[e.to] = newCost;
                        pq.offer(new int[]{e.to, newCost});
                    }
                }
            }

            System.out.println(dist[goal] == Integer.MAX_VALUE ? -1 : dist[goal]);
        }
        sc.close();
    }

    static int getFare(int[] table, int distance) {
        // table[0] = 0, table[1] = first distance threshold, etc.
        // Fare is defined per segment thresholds
        int fare = 0;
        int remaining = distance;
        for (int i = 1; i < table.length && remaining > 0; i++) {
            int segmentLen = table[i] - table[i - 1];
            int take = Math.min(segmentLen, remaining);
            fare += take * i; // i is the fare per unit distance in this segment
            remaining -= take;
        }
        return fare;
    }
}

