    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int N = sc.nextInt(); // stations
            if (N == 0) break;
            int M = sc.nextInt(); // companies
            int[][] fareTable = new int[M][];
            int[][] fareThreshold = new int[M][];
            // Read fare tables
            for (int i = 0; i < M; i++) {
                int K = sc.nextInt();
                fareThreshold[i] = new int[K];
                fareTable[i] = new int[K];
                for (int j = 0; j < K; j++) {
                    fareThreshold[i][j] = sc.nextInt();
                    fareTable[i][j] = sc.nextInt();
                }
            }
            int E = sc.nextInt();
            List<int[]>[] adj = new List[N];
            for (int i = 0; i < N; i++) adj[i] = new ArrayList<>();
            for (int i = 0; i < E; i++) {
                int u = sc.nextInt(), v = sc.nextInt(), c = sc.nextInt(), d = sc.nextInt();
                adj[u].add(new int[]{v, c, d});
                adj[v].add(new int[]{u, c, d});
            }
            int start = sc.nextInt(), goal = sc.nextInt();
            // State: (fare_so_far, station, company(-1 if none), dist_on_company)
            // Use Dijkstra
            Map<String, Integer> dist = new HashMap<>();
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            pq.offer(new int[]{0, start, -1, 0});
            int ans = -1;
            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int fare = cur[0], st = cur[1], comp = cur[2], d = cur[3];
                String key = st + "," + comp + "," + d;
                if (dist.containsKey(key)) continue;
                dist.put(key, fare);
                if (st == goal) {
                    // Pay remaining fare
                    int totalFare = fare;
                    if (comp != -1) totalFare += getFare(fareThreshold[comp], fareTable[comp], d);
                    if (ans == -1 || totalFare < ans) ans = totalFare;
                    break;
                }
                for (int[] edge : adj[st]) {
                    int nst = edge[0], nc = edge[1], nd = edge[2];
                    if (nc == comp) {
                        // Same company, accumulate distance
                        int newD = d + nd;
                        String nkey = nst + "," + nc + "," + newD;
                        if (!dist.containsKey(nkey)) pq.offer(new int[]{fare, nst, nc, newD});
                    } else {
                        // Switch company: pay current fare
                        int payNow = fare + (comp == -1 ? 0 : getFare(fareThreshold[comp], fareTable[comp], d));
                        String nkey = nst + "," + nc + "," + nd;
                        if (!dist.containsKey(nkey)) pq.offer(new int[]{payNow, nst, nc, nd});
                    }
                }
            }
            System.out.println(ans);
        }
    }
    static int getFare(int[] thresholds, int[] fares, int d) {
        for (int i = thresholds.length - 1; i >= 0; i--) {
            if (d >= thresholds[i]) return fares[i];
        }
        return fares[0];
    }
}

