/*
 *  Railway companies + fare table shortest path
 *
 *  We model each movement state as:
 *    - currently at station s
 *    - either not riding any company (free state), or
 *    - currently riding company c and have already traveled d distance on that company
 *
 *  While staying on the same company, additional fare is charged only when the total
 *  traveled distance enters a higher fare bracket. Transferring to another company
 *  ends the current ride and starts a new one from distance 0.
 *
 *  Input format handled by this solution:
 *    Repeated datasets until EOF.
 *
 *    n m c s g
 *      n : number of stations
 *      m : number of railway lines
 *      c : number of companies
 *      s : start station
 *      g : goal station
 *
 *    For each company i = 1..c:
 *      k
 *      then k lines: dist fare
 *      (fare table breakpoints in increasing dist order; fare for traveled distance x
 *       is the fare of the first breakpoint with dist >= x)
 *
 *    Then m lines:
 *      u v company distance
 *
 *  Notes:
 *    - Stations are assumed 1-indexed in input.
 *    - If goal is unreachable, print -1.
 *
 *  This is solved by Dijkstra on expanded states.
 */
public class Main {

    static final long INF = Long.MAX_VALUE / 4;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, company, dist;
        Edge(int to, int company, int dist) {
            this.to = to;
            this.company = company;
            this.dist = dist;
        }
    }

    static class FareTable {
        int[] dist;
        long[] fare;

        FareTable(int[] dist, long[] fare) {
            this.dist = dist;
            this.fare = fare;
        }

        long getFare(int d) {
            int idx = Arrays.binarySearch(dist, d);
            if (idx < 0) idx = -idx - 1;
            if (idx >= fare.length) return INF; // distance beyond table => impossible
            return fare[idx];
        }

        long additionalFare(int oldDist, int add) {
            long a = getFare(oldDist);
            long b = getFare(oldDist + add);
            if (a >= INF || b >= INF) return INF;
            return b - a;
        }

        long startFare(int add) {
            return getFare(add);
        }
    }

    static class State implements Comparable<State> {
        long cost;
        int station;
        int company;   // 0 = not riding
        int traveled;  // valid only if company != 0

        State(long cost, int station, int company, int traveled) {
            this.cost = cost;
            this.station = station;
            this.company = company;
            this.traveled = traveled;
        }

        public int compareTo(State o) {
            return Long.compare(this.cost, o.cost);
        }
    }

    static long solveOne(
            int n, int m, int c, int start, int goal,
            FareTable[] fares, List<Edge>[] graph) {

        // For each station:
        //   bestFree[station] = best cost when not riding any company.
        //   bestRide[station][company] : map traveled distance -> best cost.
        long[] bestFree = new long[n + 1];
        Arrays.fill(bestFree, INF);

        @SuppressWarnings("unchecked")
        HashMap<Integer, Long>[][] bestRide = new HashMap[n + 1][c + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= c; j++) bestRide[i][j] = new HashMap<>();
        }

        PriorityQueue<State> pq = new PriorityQueue<>();
        bestFree[start] = 0;
        pq.add(new State(0, start, 0, 0));

        long answer = INF;

        while (!pq.isEmpty()) {
            State cur = pq.poll();

            if (cur.company == 0) {
                if (cur.cost != bestFree[cur.station]) continue;
            } else {
                Long v = bestRide[cur.station][cur.company].get(cur.traveled);
                if (v == null || cur.cost != v) continue;
            }

            if (cur.station == goal) {
                answer = cur.cost;
                break;
            }

            // Option to end current ride at this station
            if (cur.company != 0 && cur.cost < bestFree[cur.station]) {
                bestFree[cur.station] = cur.cost;
                pq.add(new State(cur.cost, cur.station, 0, 0));
            }

            for (Edge e : graph[cur.station]) {
                if (cur.company == 0) {
                    // Start a new ride with e.company
                    long add = fares[e.company].startFare(e.dist);
                    if (add >= INF) continue;
                    long nc = cur.cost + add;
                    HashMap<Integer, Long> map = bestRide[e.to][e.company];
                    Long old = map.get(e.dist);
                    if (old == null || nc < old) {
                        map.put(e.dist, nc);
                        pq.add(new State(nc, e.to, e.company, e.dist));
                    }
                } else if (cur.company == e.company) {
                    // Continue on same company
                    long add = fares[e.company].additionalFare(cur.traveled, e.dist);
                    if (add >= INF) continue;
                    int nd = cur.traveled + e.dist;
                    long nc = cur.cost + add;
                    HashMap<Integer, Long> map = bestRide[e.to][e.company];
                    Long old = map.get(nd);
                    if (old == null || nc < old) {
                        map.put(nd, nc);
                        pq.add(new State(nc, e.to, e.company, nd));
                    }
                } else {
                    // Need to transfer first, which is equivalent to starting from free state here
                    long add = fares[e.company].startFare(e.dist);
                    if (add >= INF) continue;
                    long nc = cur.cost + add;
                    HashMap<Integer, Long> map = bestRide[e.to][e.company];
                    Long old = map.get(e.dist);
                    if (old == null || nc < old) {
                        map.put(e.dist, nc);
                        pq.add(new State(nc, e.to, e.company, e.dist));
                    }
                }
            }
        }

        return answer >= INF ? -1 : answer;
    }

