#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to;
    int company;
    int dist;
};

static const long long INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int N, M, C, S, G;
        cin >> N >> M >> C >> S >> G;
        if (!cin) return 0;
        if (N == 0 && M == 0 && C == 0 && S == 0 && G == 0) break;

        --S; --G;

        vector<vector<int>> fare(C, vector<int>(N + 1));
        for (int i = 0; i < C; ++i) {
            for (int d = 0; d <= N; ++d) cin >> fare[i][d];
        }

        vector<vector<Edge>> graph(N);
        for (int i = 0; i < M; ++i) {
            int x, y, d, c;
            cin >> x >> y >> d >> c;
            --x; --y; --c;
            graph[x].push_back({y, c, d});
            graph[y].push_back({x, c, d});
        }

        // State: (station, current company; C means "not on any company yet", accumulated distance on current company)
        // When moving on same company, just increase distance.
        // When changing company, pay fare of previous company for its accumulated distance.
        int NONE = C;

        vector<vector<long long>> dist(N, vector<long long>((C + 1) * (N + 1), INF));

        auto id = [&](int company, int usedDist) {
            return company * (N + 1) + usedDist;
        };

        priority_queue<
            pair<long long, tuple<int,int,int>>,
            vector<pair<long long, tuple<int,int,int>>>,
            greater<pair<long long, tuple<int,int,int>>>
        > pq;

        dist[S][id(NONE, 0)] = 0;
        pq.push({0, {S, NONE, 0}});

        long long ans = -1;

        while (!pq.empty()) {
            auto [cost, st] = pq.top();
            pq.pop();

            auto [u, comp, used] = st;
            int idx = id(comp, used);
            if (cost != dist[u][idx]) continue;

            if (u == G) {
                long long total = cost;
                if (comp != NONE) total += fare[comp][used];
                ans = total;
                break;
            }

            for (auto &e : graph[u]) {
                int v = e.to;
                int nc = e.company;
                int nd = e.dist;

                if (comp == NONE) {
                    if (nd <= N) {
                        int nidx = id(nc, nd);
                        if (cost < dist[v][nidx]) {
                            dist[v][nidx] = cost;
                            pq.push({cost, {v, nc, nd}});
                        }
                    }
                } else if (comp == nc) {
                    if (used + nd <= N) {
                        int nidx = id(comp, used + nd);
                        if (cost < dist[v][nidx]) {
                            dist[v][nidx] = cost;
                            pq.push({cost, {v, comp, used + nd}});
                        }
                    }
                } else {
                    long long ncost = cost + fare[comp][used];
                    if (nd <= N) {
                        int nidx = id(nc, nd);
                        if (ncost < dist[v][nidx]) {
                            dist[v][nidx] = ncost;
                            pq.push({ncost, {v, nc, nd}});
                        }
                    }
                }
            }
        }

        cout << ans << '\n';
    }

    return 0;
}
